# Solution for Lieges of Legendre game theory problem

def solution(input_str):
    import sys
    from functools import lru_cache

    data = input_str.strip().split('\n')
    n, k = map(int, data[0].split())
    a = list(map(int, data[1].split()))

    @lru_cache(maxsize=None)
    def grundy(x):
        if x == 0:
            return 0

        # Option 1: Remove 1 cow
        reachable = {grundy(x - 1)}

        # Option 2: If x is even, replace with k piles of x/2
        if x % 2 == 0:
            half = x // 2
            if k % 2 == 1:
                # k is odd: XOR of k copies of grundy(half) = grundy(half)
                reachable.add(grundy(half))
            else:
                # k is even: XOR of k copies of grundy(half) = 0
                reachable.add(0)

        # Compute MEX (Minimum Excluded value)
        mex = 0
        while mex in reachable:
            mex += 1
        return mex

    # Compute XOR sum of all Grundy numbers
    xor_sum = 0
    for val in a:
        xor_sum ^= grundy(val)

    # Non-zero XOR means first player wins (Kevin), zero means second player wins (Nicky)
    if xor_sum > 0:
        return "Kevin\n"
    else:
        return "Nicky\n"

