        if x in computed:
            return computed[x]

        # Option 1: Remove 1 cow
        reachable = {grundy(x - 1)}

        # Option 2: If x is even, replace with k piles of x/2
        if x % 2 == 0:
            half = x // 2
            if k % 2 == 1:
                reachable.add(grundy(half))
            else:
                reachable.add(0)

        # Compute MEX
        mex = 0
        while mex in reachable:
            mex += 1
        computed[x] = mex
        return mex

    # Compute XOR sum of all Grundy numbers
    xor_sum = 0
    for val in a:
        xor_sum ^= grundy(val)

    # Non-zero XOR means first player wins (Kevin), zero means second player wins (Nicky)
    if xor_sum > 0:
        return "Kevin\n"
    else:
        return "Nicky\n"

