    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    ans = [-1] * (m + 1)  # 1-indexed, ans[0] unused
    reached = [set() for _ in range(n + 1)]
    reached[0] = {0}

    # Parse operations
    ops = []
    for i in range(n):
        t, x_prime, y = map(int, lines[i + 1].split())
        ops.append((t, x_prime, y))

    for step in range(n):
        t, x_prime, y = ops[step]

        for val in reached[step]:
            # For j from 1 to y: compute result of applying operation j times
            for j in range(1, y + 1):
                if t == 1:
                    # Type 1: ceil(val + x_prime / 100000) = val + ceil(x_prime / 100000)
                    inc = (x_prime + 99999) // 100000
                    new_val = val + j * inc
                else:
                    # Type 2: ceil(val * x_prime / 100000)
                    new_val = (val * x_prime + 99999) // 100000
                j_val = val
                for _ in range(j):
                    if t == 1:
                        j_val = (j_val + x_prime + 99999) // 100000
                    else:
                        j_val = (j_val * x_prime + 99999) // 100000
                    if j_val > m:
                        break

                if j_val <= m and j_val >= 1 and not reached[step + 1][1]:
                    if ans[j_val] == -1:
                        ans[j_val] = step + 1
                        new_reached_vals.append(j_val)

    # Mark values in reached[step+1]
    for val in new_reached_vals:
        reached[step + 1].add(val)

    # Build result
    result = []
    for j in range(1, m + 1):
        result.append(str(ans[j]))

    return ' '.join(result) + ' '

