def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    def is_geometric(a):
        length = len(a)
        # Single element or empty is always a GP
        if length <= 1:
            return True

        # All zeros is a GP
        if all(x == 0 for x in a):
            return True

        # If first element is 0, all must be 0 (handled by all zeros check)
        # But need to separate check for when first is 0 but not all zeros
        if a[0] == 0:
            for x in a[1:]:
                if x != 0:
                    return False
            return True

        # Get the common ratio from first two elements
        ratio = a[1] / a[0]

        # Check all consecutive pairs have the same ratio
        for i in range(2, length):
            if abs(a[i] / a[i-1] - ratio) > 1e-9:
                return False

        return True

    # First check if the array is already a GP
    if is_geometric(arr):
        return '0\n'

    # Try removing each element and check if remaining is a GP
    for i in range(len(arr)):
        new_arr = arr[:i] + arr[i+1:]
        if is_geometric(new_arr):
            return '1\n'

    # Not a GP and not possible to make GP by removing one element
    return '2\n'

