from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "-1"

    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    edges = []
    for i in range(m):
        parts = list(map(int, lines[2 + i].split()))
        u, v, w = parts[0], parts[1], parts[2]
        edges.append((u, v, w, i + 1))

    # Build adjacency list, excluding specified edge indices
    def build_adj(excluded_edges=None):
        adj = [[] for _ in range(n + 1)]
        for u, v, w, idx in edges:
            if idx not in excluded_edges:
                adj[u].append(v)
                adj[v].append(u)
        return adj

    # BFS to check connectivity from start to end
    def bfs(start, end, adj):
        if start == end:
            return True
        visited = [False] * (n + 1)
        queue = deque([start])
        visited[start] = True
        while queue:
            u = queue.popleft()
            if u == end:
                return True
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
        return False

    # Check if s and t are already disconnected
    if not bfs(s, t, build_adj()):
        return "0\n0\n"

    # Find minimum 1-edge cut
    best_1cut_cost = float('inf')
    best_1cut_idx = None

    for u, v, w, idx in edges:
        if not bfs(s, t, build_adj({idx})):
            if w < best_1cut_cost:
                best_1cut_cost = w
                best_1cut_idx = idx

    if best_1cut_idx is not None and best_1cut_cost < float('inf'):
        return f"{best_1cut_cost}\n1\n{best_1cut_idx}"

    # Find minimum 2-edge cut
    best_2cut_cost = float('inf')
    best_2cut_edges = None

    # Sort edges by weight for optimization
    sorted_edges = sorted(edges, key=lambda x: x[2])

    for i in range(len(sorted_edges)):
        u1, v1, w1, e1 = sorted_edges[i]

        # Early exit if cost exceeds best found 2-edge cut
        if best_2cut_cost <= w1:
            break

        # Try combining with other edges
        for j in range(i + 1, len(sorted_edges)):
            if best_2cut_cost <= w1 + sorted_edges[j][2]:
                break

            u2, v2, w2, e2 = sorted_edges[j]

            if not bfs(s, t, build_adj({e1, e2})):
                total = w1 + w2
                if total < best_2cut_cost:
                    best_2cut_cost = total
                    best_2cut_edges = (e1, e2)

    if best_2cut_edges:
        e1, e2 = best_2cut_edges
        return f"{best_2cut_cost}\n2\n{e1} {e2}"

    return "-1"

def solution(input_str):
    import sys
    sys.setrecursionlimit(100000)

    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    def f(x):
        while x % k == 0:
            x //= k
        return x

    def get_unused_numbers(nums, used):
        # Get indices that are not used
        available = [i for i in range(len(nums)) if i not in unused]
        return available

    def solve(nums, operations, target=1):
        if len(nums) == 1:
            return nums[0] == 1 and None  # Return None if success, else indicate failure

        best_result = None

        # Try all pairs
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                x = nums[i]
                y = nums[j]
                new_val = f(x + y)

                # Create new list without these two and with the new value
                new_nums = nums[:i] + nums[i+1:j] + nums[j+1:] + [new_val]

                # Record operation (values, not indices)
                op = (x, y)

                result = solve(new_nums, [(op,) + operations])

                if result is True:
                    return True

                # Try to find a solution with this operation
                final = solve(new_nums, operations + [op])
                if final is True:
                    return True

        return False

    # We need to track what combinations of operations work
    def helper(nums, operations_list):
        if len(nums) == 1:
            if nums[0] == 1:
                return operations_list
            else:
                return None

        # Try all pairs
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                x = nums[i]
                y = nums[j]
                new_val = f(x + y)

                # Build new list
                new_nums = nums[:i] + nums[i+1:j] + nums[j+1:] + [new_val]

                # Recurse
                result = helper(new_nums, operations_list + [(x, y)])
                if result is not None:
                    return result

        return None

    # BFS/DFS to find solution
    from collections import deque
    operations = []

    def dfs(nums, ops):
        if len(nums) == 1:
            if nums[0] == 1:
                return ops
            return None

        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                x = nums[i]
                y = nums[j]
                new_val = f(x + y)

                new_nums = nums[:i] + nums[i+1:j] + nums[j+1:] + [new_val]

                result = dfs(new_nums, ops + [(x, y)])
                if result is not None:
                    return result

        return None

    result = dfs(a, [])

    if result is None:
        return "NO"

    output = ["YES"]
    for op in result:
        output.append(f"{op[0]} {op[1]}")

    return '\n'.join(output)

