def solution(input_str):
    input_str = input_str.strip()
    lines = input_str.split('\n')

    if not lines or not lines[0]:
        return "NO"

    n, m = map(int, lines[0].split())

    # 2-SAT problem: each variable vi (1≤vi≤m)
    # Node representation: 2*(vi-1) = vi (true), 2*(vi-1)+1 = vi (false)

    adj = [[] for _ in range(2 * m)]

    def lit_to_node(lit):
        """Convert literal to node index"""
        return (2 * (abs(lit) - 1)) if lit > 0 else (2 * (abs(lit) - 1) + 1)

    def var_to_node(var, val):
        """Convert var and truth value to node index"""
        if val:  # true
            return 2 * (var - 1)
        else:  # false
            return 2 * (var - 1) + 1

    # Build implication graph from clauses
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        literals = parts[1:]

        # For clause (l1 v l2 v ... vk), if ¬lj then at least one of remaining literals must be true
        for idx1 in range(len(literals)):
            l1 = literals[idx1]
            src = lit_to_node(l1)
            for idx2 in range(len(literals)):
                if idx2 > idx1:
                    l2 = literals[idx2]
                    # Edge: ¬l1 → l2
                    neg_l1 = lit_to_node(-l1)
                    adj[neg_l1].append(lit_to_node(l2))

    # Tarjan's algorithm for SCC
    disc = [-1] * (2 * m)
    low = [-1] * (2 * m)
    on_stack = [False] * (2 * m)
    stack = []
    timer = [0]
    scc_id = [-1] * (2 * m)
    scc_cnt = [0]

    def dfs(node):
        disc[node] = low[node] = timer[0]
        timer[0] += 1
        stack.append(node)
        on_stack[node] = True

        for neighbor in adj[node]:
            if disc[neighbor] == -1:
                dfs(neighbor)
                low[node] = min(low[node], low[neighbor])
            elif on_stack[neighbor]:
                low[node] = min(low[node], disc[neighbor])

        if disc[node] == low[node]:
            while stack:
                top = stack.pop()
                on_stack[top] = False
                scc_id[top] = scc_cnt[0]
                if top == node:
                    break
            scc_cnt[0] += 1

    for i in range(2 * m):
        if disc[i] == -1:
            dfs(i)

    # Check for conflicts
    for i in range(m):
        var_true = scc_id[2 * i]
        var_false = scc_id[2 * i + 1]
        if var_true == var_false:
            return "NO"

    # Build solution (simplify: always set to true for consistent variables)
    assignment = []
    for i in range(m):
        assignment.append("1")

    return "YES\n" + "".join(assignment)

