        # BFS traversal for this component
        queue = [node]
        visited[node] = True
        x[node] = 0.0  # Arbitrary starting value

        idx = 0
        while idx < len(queue):
            u = queue[idx]
            idx += 1

            for v, c in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    # Propagate constraint
                    if c == 1:  # black edge
                        x[v] = 1.0 - x[u]
