    if n == 0:
        return "-1\n"

    a = list(map(int, lines[1].split()))

    # Single box with value > 0: no moves needed (all divisible by sum if sum > 1)
    # But sum must have divisor > 1
    total_sum = sum(a)

    if total_sum == 1:
        return "-1\n"

    # Find all divisors of total_sum
    divisors = set()
    for i in range(1, int(total_sum**0.5) + 1):
        if total_sum % i == 0:
            divisors.add(i)
            divisors.add(total_sum // i)

    min_cost = float('inf')

    for k in divisors:
        if k > 1:
            # Calculate cost for this divisor k
            # The cost is sum of prefix sums mod k for all positions except the last
            cost = 0
            current = 0
            for i in range(n - 1):
                current += a[i]
                cost += current % k

            if cost < min_cost:
                min_cost = cost

    if min_cost == float('inf'):
        return "-1\n"
    else:
        return f"{min_cost}\n"

