    def is_bitonic(arr):
        """Check if array is bitonic (increases then decreases)"""
        if not arr or len(arr) <= 1:
            return True
        max_idx = arr.index(max(arr))
        # Check before max: strictly increasing
        for i in range(max_idx):
            if arr[i] >= arr[i + 1]:
                return False
        # Check after max: strictly decreasing
        for i in range(max_idx, len(arr) - 1):
            if arr[i] <= arr[i + 1]:
                return False
        return True

    # Check if all rows are bitonic
    for i in range(n):
        if not is_bitonic(grid[i]):
            return "-1"

    # Check if all columns are bitonic
    for j in range(m):
        col = [grid[i][j] for i in range(n)]
        if not is_bitonic(col):
            return "-1"

    # If all checks pass, return the original matrix
    return input_str

