    """
    Solution for the matrix partition problem.

    This function:
    1. Parses n and m from the input
    2. Tries to construct the matrix from available integers
    3. For each valid (r, c) where r|n and c|m, checks if all r×c rectangles are equal
    4. Returns the count of valid pairs
    """
    lines = [line.strip() for line in input_str.strip().split('\n') if line.strip()]

