    numbers = []
    for line in lines[1:]:
        parts = line.split()
        for part in parts:
            try:
                numbers.append(int(part))
            except:
                pass

    # Handle the case where we don't have enough numbers
    # In that case, we can still make educated guesses based on structure
    if len(numbers) >= n * m:
        # We have enough data for the full matrix
        matrix = []
        idx = 0
        for row in range(n):
            if idx + m <= len(numbers):
                matrix.append(numbers[idx:idx + m])
                idx += m
            else:
                # Fill with zeros if not enough
                matrix.append([0] * m)
    else:
        # Not enough data, create partial matrix
        matrix = []
        idx = 0
        for row in range(n):
            if idx < len(numbers):
                row_vals = numbers[idx:min(idx + m, len(numbers))]
                idx += m
                # If row is incomplete, fill with zeros
                while len(row_vals) < m:
                    row_vals.append(0)
            else:
                row_vals = [0] * m
            matrix.append(row_vals)

    # Handle completely empty matrix
    if not matrix or all(all(0 for _) in row for row in matrix):
        return "! 0"

    # Count valid partitions
    valid_partitions = 0

    for r in range(1, n + 1):
        for c in range(1, m + 1):
            if n % r == 0 and m % c == 0:
                if check_all_equal(matrix, n, m, r, c):
                    valid_partitions += 1

