def get_flat_rect(matrix, top, left, r, c):
    """Get flattened tuple representation of rectangle at (top, left) with size r×c"""
    flat = []
    for i in range(top, min(top + r, len(matrix))):
        row = matrix[i]
        flat.extend(row[left:min(left + c, len(row))])
    return tuple(flat)


def check_all_equal(matrix, n, m, r, c):
    """
    Check if all r×c rectangles that can be formed from the matrix are equal.
    The rectangles are formed by dividing into (n/r) rows and (m/c) columns of rectangles.
    n/r must be at least 1 and m/c must be at least 1.
    """
    n_rects = n // r
    m_rects = m // c

    if n_rects <= 0 or m_rects <= 0:
        return False

    # Get the reference rectangle from position (0, 0)
    ref = get_flat_rect(matrix, 0, 0, r, c)

    # Check all other rectangles against the reference
    for ri in range(1, n_rects):
        for ci in range(m_rects):
            rect = get_flat_rect(matrix, ri * r, ci * c, r, c)
            if rect != ref:
                return False

    # If only one rectangle (ri=0, ci=0), it's trivially valid
    return True


def check_all_equal_low_idx(matrix, n, m, r, c):
    """
    Alternative approach: use full grid coverage, compare adjacent rects
    """
    n_rects = n // r
    m_rects = m // c

    if n_rects <= 0 or m_rects <= 0:
        return False

    ref = get_flat_rect(matrix, 0, 0, r, c)

    for ri in range(n_rects):
        for ci in range(m_rects):
            rect = get_flat_rect(matrix, ri * r + 0, ci * c + 0, r, c)
            if rect != ref:
                return False

    return True

