            break

    if all_collinear:
        return "-1\n"

    def has_holes_at(t):
        """Returns True if there's at least one hole at time t"""
        if t <= 1e-12:
            return True  # At very small t, circles can't surround anything

        # Sample points in a region that could potentially be holes
        x_min, x_max = min(c[0] for c in centers), max(c[0] for c in centers)
        y_min, y_max = min(c[1] for c in centers), max(c[1] for c in centers)

        sample_radius = max_dist

