            y = random.uniform(y_min - sample_radius * 0.5, y_max + sample_radius * 0.5)

            # Check if point is covered by any circle
            covered = False
            for cx, cy in centers:
                if (x - cx) ** 2 + (y - cy) ** 2 <= t ** 2 + 1e-9:
                    covered = True
                    break

            # If point is not covered, it could be in a hole
            if not covered:
                # Additional check: is point surrounded by circles?
                # For simplicity, if not covered, assume there's a hole
                return True

        return False

    def has_holes_at_deterministic(t):
        """Deterministic check that doesn't rely on randomness"""
        if t <= 1e-12:
            return True

        x_min, x_max = min(c[0] for c in centers), max(c[0] for c in centers)
        y_min, y_max = min(c[1] for c in centers), max(c[1] for c in centers)

        # Use grid sampling for deterministic check
        if x_max - x_min > 10000:
            grid_step = max_dist
        else:
            grid_step = 100.0

        for x in [x_min + i * grid_step for i in range(int((x_max - x_min) / grid_step) + 2)]:
            for y in [y_min + j * grid_step for j in range(int((y_max - y_min) / grid_step) + 2)]:
                # Add some noise points too
                x_noise = x + random.uniform(-grid_step/3, grid_step/3)
                y_noise = y + random.uniform(-grid_step/3, grid_step/3)
                x_noise, y_noise = round(x_noise, 2), round(y_noise, 2)

                if not is_covered(x_noise, y_noise, t, centers):
                    return True

        return False

    def is_covered(px, py, t, centers):
        """Check if point (px, py) is covered by any circle of radius t"""
        for cx, cy in centers:
            if (px - cx) ** 2 + (py - cy) ** 2 <= t ** 2 + 1e-9:
                return True
        return False

    # Binary search for the exact moment
    # We want the last time when there's a hole (check returns True)
    low = 0.0
    high = max_dist  # Upper bound

    # Refine upper bound
    if has_holes_at_deterministic(high):
