            test_t = max_dist * mult
            if has_holes_at_deterministic(test_t):
                low = test_t
            else:
                high = test_t
                break

    # Main binary search
    for _ in range(100):
        mid = (low + high) / 2
        if has_holes_at_deterministic(mid):
            low = mid  # Continue searching for later time with holes
        else:
            high = mid  # No more holes, answer is before this

