def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines or not lines[0]:
        return "0"

    try:
        n, m = map(int, lines[0].split())
    except:
        return "0"

    attempts = []
    for i in range(1, len(lines)):
        parts = lines[i].split()
        if len(parts) >= 2:
            attempts.append((parts[0], int(parts[1])))

    # No constraints = all 2^n codes valid
    if m == 0:
        return f"{1 << n}"

    # Small n: brute force with direct checking
    if n <= 20:
        count = 0
        for i in range(1 << n):
            code = format(i, f'0{n}b')
            valid = True
            for s, c in attempts:
                matches = sum(1 for j in range(n) if code[j] == s[j])
                if matches != c:
                    valid = False
                    break
            if valid:
                count += 1
        return str(count)

    # Use backtracking with pruning for larger n
    # Precompute bit positions for pruning
    patterns = [a[0] for a in attempts]
    targets = [a[1] for a in attempts]

    count = 0
    current_matches = [0] * m

    def backtrack(pos):
        nonlocal count

        if pos == n:
            # Valid code found
            count += 1
            return

        for bit in [0, 1]:
            # Check pruning before exploring
            can_extend = True
            for i, pattern in enumerate(patterns):
                potential_matches = current_matches[i]
                if bit == int(pattern[pos]):
                    potential_matches += 1

                # Cannot exceed target with remaining positions filled optimally
                remaining_pos = n - pos - 1
                if potential_matches > targets[i]:
                    can_extend = False
                    break

                # Must be able to reach target (target - potential_matches) with remaining positions
                needed = targets[i] - potential_matches
                if needed < 0 or needed > remaining_pos:
                    can_extend = False
                    break

            if can_extend:
                # Apply bit and explore
                for i, pattern in enumerate(patterns):
                    if bit == int(pattern[pos]):
                        current_matches[i] += 1
                backtrack(pos + 1)
                # Backtrack
                for i, pattern in enumerate(patterns):
                    if bit == int(pattern[pos]):
                        current_matches[i] -= 1

    backtrack(0)
    return str(count)

from collections import deque

def solution(s):
    n = int(s.strip())

    if n == 0:
        return '0\n'

    # BFS to find minimum operations to reach 0
    visited = {n}
    queue = deque([(n, 0)])

    while queue:
        num, dist = queue.popleft()

        s_num = str(num)

        for c in s_num:
            d = int(c)
            if d > 0:
                new_num = num - d
                if new_num == 0:
                    return f'{dist + 1}\n'
                if new_num not in visited:
                    visited.add(new_num)
                    queue.append((new_num, dist + 1))

    return '0\n'
